import regex as re
import glob
import os
from openpyxl import load_workbook

def task_func(directory_path='./xlsx_files/'):
    """
    Protect all double quotes in all Excel (.xlsx) files in the specified directory
    by prefixing them with a double backslash.

    Args:
        directory_path (str): Directory containing .xlsx files.

    Returns:
        int: The number of Excel files processed.
    """
    if not os.path.isdir(directory_path):
        return 0

    processed_files = 0
    pattern = os.path.join(directory_path, '*.xlsx')

    for file_path in glob.glob(pattern):
        if os.path.basename(file_path).startswith('~$'):
            continue

        try:
            workbook = load_workbook(file_path)
        except Exception:
            continue

        changed = False

        for worksheet in workbook.worksheets:
            for row in worksheet.iter_rows():
                for cell in row:
                    value = cell.value
                    if isinstance(value, str) and cell.data_type != 'f':
                        new_value = value.replace('"', '\\\\\"')
                        if new_value != value:
                            cell.value = new_value
                            changed = True

        try:
            workbook.save(file_path)
            processed_files += 1
        except Exception:
            continue

    return processed_files
